-- ENEM 2025 - 1o dia (Linguagens + Ciencias Humanas) - questoes baseadas em imagem.
-- Gabarito lido de foto (OCR). Revise correct_index se necessario.
-- Rode 0008_question_images.sql antes (ou garanta colunas source_images/stem_image_url).


on conflict (source_ref) do update set
  stem_image_url = excluded.stem_image_url,
  source_images = excluded.source_images,
  options = excluded.options,
  correct_index = excluded.correct_index,
  subject_id = excluded.subject_id,
  topic = excluded.topic,
  status = excluded.status;